#!/usr/bin/env bash
# reos: single-file Debian network reinstall tool.
# Generated by CI using tools/build-script.py; edit src/bash and src/assets instead.
# SPDX-License-Identifier: MIT
set -Eeuo pipefail
export LC_ALL=C
umask 077
PROGRAM_VERSION=0.1.0
WORK=
LOG_ACTIVE=0

die() { printf 'reos: %s\n' "$*" >&2; exit 1; }
message() {
    printf '%s\n' "$*"
    if (( LOG_ACTIVE )); then printf '[%(%FT%T%z)T] %s\n' -1 "$*" >> /var/log/reos.log; fi
}
cleanup() { if [[ -n $WORK && -d $WORK ]]; then rm -rf -- "$WORK"; fi; }
need() { command -v "$1" >/dev/null 2>&1 || die "Required command missing: $1"; }
scratch() {
    [[ -n $WORK ]] && return 0
    WORK=$(mktemp -d -t reos.XXXXXXXX)
    trap cleanup EXIT
    trap 'exit 130' INT
    trap 'exit 143' TERM
}

defaults() {
    Suite=stable Mirror='' Proxy='' IP='' Netmask='' Gateway='' DNS='' IPv6='' IPv6Gateway='' IPv6DNS=''
    Hostname='' Interface=auto Username=root Password='' SSHPort=22 AuthorizedKeysURL=''
    Disk='' ESPSize=106 SystemSize='' SystemSizeMB=0
    Install='ca-certificates curl' PostInstall='' Firmware=0
    SwapSize='' SwapMB=0 Optimize=1 Unattended=1 InstallerSSH=1 Timezone=UTC NTP=''
    Kernel='' CloudKernel=0 Keyring=''
    DryRun=0 RebootNow=0 Yes=0 DNSExplicit=0
    KeepParts=() KeepPaths=() KeepFstab=() Mirrors=()
    Static=0 EFI=0 DiskLabel=gpt Arch=amd64 NonFreeFirmware=1
    Interfaces='' ResolvConf='' SecurityRepo='' SecuritySuite='' AuthorizedKeys=''
    InstallerOnlink=0 InstallerV6Address='' InstallerV6Interface='' InstallerV6Gateway=''
    InstallerV6Prefix=64 IPPrefix=24 Home=/root KeysB64='' PostInstallB64='' Swap=0
    PasswordHash='' ReleaseNumber=0 RootDevice='' DiskID='' RootPartUUID=''
}

usage() {
    cat <<'HELP'
reos: reinstall Debian through a one-time GRUB entry
Usage: bash reos.sh [OPTIONS] | status | logs [firstboot|cleanup|all] | reset

  --version 12|13|stable    Debian release (default: stable)
  --mirror URL --proxy URL
  --interface NAME --ip ADDR --netmask MASK --gateway ADDR --dns "ADDR ..."
  --ipv6 ADDR[/PREFIX] --ipv6-gateway ADDR --ipv6-dns "ADDR ..."
  --hostname NAME --user NAME --password PASS --ssh-port PORT
  --authorized-keys-url URL
  --disk /dev/vda
  --esp MB --system-size SIZE
  --keep-part /dev/vda3 (repeatable)
  --install "PKG ..." --post-install PATH|URL
  --firmware
  --swap-size SIZE --timezone ZONE --ntp HOST
  --cloud-kernel
  --optimize=false --unattended=false --installer-ssh=false
  --keyring PATH
  --dry-run --yes --reboot-now
  -V, --program-version      Program version
  -h, --help                 Show this help

Boolean flags accept =true or =false. Preparation requires root and Debian/GRUB2.
Installation repartitions the target disk. Save credentials before rebooting.
HELP
}

parse() {
    local raw name val field boolean
    while (( $# )); do
        raw=$1; shift
        case $raw in -h|--help|help) usage; exit 0;; -V|--program-version) printf '%s\n' "$PROGRAM_VERSION"; exit 0;; esac
        [[ $raw == -* ]] || die "Unknown option: $raw"
        name=${raw#-}; name=${name#-}; name=${name%%=*}
        boolean=0
        case $name in
            version) field=Suite;; mirror) field=Mirror;; proxy) field=Proxy;; ip) field=IP;; netmask) field=Netmask;; gateway) field=Gateway;; dns) field=DNS; DNSExplicit=1;;
            ipv6) field=IPv6;; ipv6-gateway) field=IPv6Gateway;; ipv6-dns) field=IPv6DNS;; hostname) field=Hostname;; interface) field=Interface;;
            user) field=Username;; password) field=Password;; ssh-port) field=SSHPort;; authorized-keys-url) field=AuthorizedKeysURL;;
            disk) field=Disk;; esp) field=ESPSize;; system-size) field=SystemSize;;
            install) field=Install;; post-install) field=PostInstall;; swap-size) field=SwapSize;; timezone) field=Timezone;; ntp) field=NTP;;
            keyring) field=Keyring;;
            keep-part) field=KeepPaths;;
            firmware) field=Firmware; boolean=1;;
            optimize) field=Optimize; boolean=1;; unattended) field=Unattended; boolean=1;; installer-ssh) field=InstallerSSH; boolean=1;;
            cloud-kernel) field=CloudKernel; boolean=1;;
            dry-run) field=DryRun; boolean=1;; reboot-now) field=RebootNow; boolean=1;; yes) field=Yes; boolean=1;;
            *) die "Unknown option: $raw";;
        esac
        if [[ $raw == *=* ]]; then val=${raw#*=}
        elif (( boolean )); then val=true
        else (( $# )) || die "Missing value for --$name"; val=$1; shift; fi
        if (( boolean )); then
            case ${val,,} in true|t|1) val=1;; false|f|0) val=0;; *) die "Invalid boolean for --$name";; esac
        elif [[ $val == *$'\n'* || $val == *$'\r'* ]]; then die "--$name must not contain newlines"; fi
        case $field in KeepPaths) KeepPaths+=("$val");; *) printf -v "$field" '%s' "$val";; esac
    done
}

ipv4_number() {
    local a b c d
    [[ $1 =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]] || return 1
    IFS=. read -r a b c d <<< "$1"
    a=$((10#$a)); b=$((10#$b)); c=$((10#$c)); d=$((10#$d))
    (( a < 256 && b < 256 && c < 256 && d < 256 )) || return 1
    printf '%u' "$(( (a<<24) | (b<<16) | (c<<8) | d ))"
}
valid_ipv6() {
    local addr=${1%%%*} left right part count=0
    local groups=()
    [[ $addr == *:* && $addr != *[^0-9a-fA-F:]* && $addr != *:::* ]] || return 1
    if [[ $addr == *::* ]]; then
        left=${addr%%::*}; right=${addr#*::}; [[ $right != *::* ]] || return 1
        addr=${left:+$left:}$right
        IFS=: read -ra groups <<< "$addr"
        for part in "${groups[@]}"; do [[ $part =~ ^[0-9a-fA-F]{1,4}$ ]] || return 1; ((count+=1)); done
        (( count < 8 ))
    else
        IFS=: read -ra groups <<< "$addr"
        (( ${#groups[@]} == 8 )) || return 1
        for part in "${groups[@]}"; do [[ $part =~ ^[0-9a-fA-F]{1,4}$ ]] || return 1; done
    fi
}
mask_prefix() {
    local n inv p=0
    n=$(ipv4_number "$1") || die "Invalid netmask: $1"
    inv=$(( (~n) & 4294967295 )); (( (inv & (inv+1)) == 0 )) || die "Non-contiguous netmask: $1"
    while (( n )); do ((p+=1)); n=$(( (n<<1) & 4294967295 )); done
    printf '%s' "$p"
}
prefix_mask() {
    local n=$(( (4294967295 << (32-$1)) & 4294967295 ))
    printf '%d.%d.%d.%d' "$((n>>24&255))" "$((n>>16&255))" "$((n>>8&255))" "$((n&255))"
}
size_mb() {
    local n unit
    [[ ${1^^} =~ ^([0-9]{1,7})([MGT])B?$ ]] || die "Invalid size: $1 (use 512M or 10G)"
    n=$((10#${BASH_REMATCH[1]})); unit=${BASH_REMATCH[2]}
    case $unit in G) n=$((n*1024));; T) n=$((n*1048576));; esac
    (( n >= 64 && n <= 1048576 )) || die 'Size must be between 64M and 1T'
    printf '%s' "$n"
}
valid_url() {
    local pattern='^https?://([a-zA-Z0-9.-]+|\[[a-fA-F0-9:]+\])(:[0-9]+)?(/[a-zA-Z0-9._~:/%+@=?&-]*)?$'
    [[ $1 =~ $pattern ]]
}
validate() {
    local value p
    [[ $Interface =~ ^[a-zA-Z0-9_.:-]{1,15}$ ]] || die 'Invalid --interface'
    [[ $Username =~ ^[a-z_][a-z0-9_-]{0,31}$ ]] || die 'Invalid --user'
    [[ $SSHPort =~ ^[0-9]{1,5}$ ]] && (( 10#$SSHPort >= 1 && 10#$SSHPort <= 65535 )) || die 'Invalid --ssh-port'
    SSHPort=$((10#$SSHPort))
    [[ $ESPSize =~ ^[0-9]{1,5}$ ]] && (( 10#$ESPSize >= 106 )) || die '--esp must be at least 106 MB'
    ESPSize=$((10#$ESPSize))
    [[ $Timezone =~ ^[a-zA-Z0-9_+/-]+$ && $Timezone != /* && $Timezone != *..* ]] || die 'Invalid --timezone'
    [[ -z $NTP || $NTP =~ ^[a-zA-Z0-9.:-]+$ ]] || die 'Invalid --ntp'
    NTP=${NTP:-time.cloudflare.com}
    [[ -z $Mirror ]] || valid_url "$Mirror" || die 'Invalid --mirror URL'
    [[ -z $Proxy || $Proxy =~ ^(https?|socks5h?)://[^[:space:]\"\'\;\`\\]+$ ]] || die 'Invalid --proxy URL'
    [[ -z $AuthorizedKeysURL ]] || valid_url "$AuthorizedKeysURL" || die 'Invalid authorized keys URL'
    [[ -z $IP ]] || ipv4_number "$IP" >/dev/null || die 'Invalid --ip'
    [[ -z $Gateway ]] || ipv4_number "$Gateway" >/dev/null || die 'Invalid --gateway'
    if [[ -n $Netmask ]]; then [[ -n $IP ]] || die '--netmask requires --ip'; mask_prefix "$Netmask" >/dev/null; fi
    if [[ -n $IPv6 ]]; then
        valid_ipv6 "${IPv6%/*}" || die 'Invalid --ipv6'
        p=64; [[ $IPv6 != */* ]] || p=${IPv6##*/}
        [[ $p =~ ^[0-9]{1,3}$ ]] && (( 10#$p <= 128 )) || die 'Invalid IPv6 prefix'
    fi
    [[ -z $IPv6Gateway ]] || { [[ -n $IPv6 ]] && valid_ipv6 "$IPv6Gateway"; } || die '--ipv6-gateway requires --ipv6 and a valid address'
    for value in $DNS $IPv6DNS; do ipv4_number "$value" >/dev/null || valid_ipv6 "$value" || die "Invalid DNS address: $value"; done
    [[ $Install != *[^a-zA-Z0-9.+:~\ /_-]* ]] || die 'Invalid package list'
    for value in $Install; do [[ $value != -* ]] || die 'Package names cannot start with -'; done
    [[ -z $Disk || $Disk =~ ^/dev/[a-zA-Z0-9_./-]+$ ]] || die 'Invalid --disk'
    for value in "${KeepPaths[@]}"; do [[ $value =~ ^/dev/[a-zA-Z0-9_./-]+$ ]] || die 'Invalid --keep-part'; done
    if [[ -n $SwapSize ]]; then SwapMB=$(size_mb "$SwapSize"); SwapSize=${SwapMB}M; Swap=1; fi
    if [[ -n $SystemSize ]]; then SystemSizeMB=$(size_mb "$SystemSize"); (( SystemSizeMB >= 2048 )) || die '--system-size must be at least 2G'; fi
}

fetch() {
    local url=$1 dest=$2 limit=${3:-67108864}
    local protocols=http,https
    official_debian_mirror "$url" && protocols=https
    local args=(--silent --show-error --fail --location --retry 2 --connect-timeout 15 --max-time 1800 --max-filesize "$limit" --proto "=$protocols" --proto-redir "=$protocols")
    [[ -z $Proxy ]] || args+=(--proxy "$Proxy")
    curl "${args[@]}" --output "$dest" --url "$url" || return 1
    [[ $(stat -c %s "$dest") -le $limit ]]
}
keyring_args() {
    KeyringArgs=(--homedir "$WORK" --keyring "${Keyring:-/usr/share/keyrings/debian-archive-keyring.gpg}")
    if [[ -z $Keyring && -f /usr/share/keyrings/debian-role-keys.gpg ]]; then KeyringArgs+=(--keyring /usr/share/keyrings/debian-role-keys.gpg); fi
}
release_file() {
    local base=$1 suite=$2 out=$3
    keyring_args
    if fetch "$base/dists/$suite/InRelease" "$out.signed" 16777216; then
        gpgv "${KeyringArgs[@]}" --output "$out" "$out.signed" 2>"$WORK/gpg-error" || return 1
    else
        fetch "$base/dists/$suite/Release" "$out" 16777216 || return 1
        fetch "$base/dists/$suite/Release.gpg" "$out.sig" 1048576 || return 1
        gpgv "${KeyringArgs[@]}" "$out.sig" "$out" 2>"$WORK/gpg-error" || return 1
    fi
    local code
    code=$(sed -n 's/^Codename: *//p' "$out")
    case $suite in stable) [[ $code =~ ^[a-z]+$ ]];; *) [[ $code == "$suite" ]];; esac
}
release_digest() {
    # Only SHA256 entries count; reject duplicate paths and malformed entries.
    awk -v path="$2" '
      /^SHA256:$/ {active=1; next}
      /^[^ \t]/ {active=0}
      active && $3 == path {count++; hash=$1; size=$2; fields=NF}
      END {if(count != 1 || fields != 3 || length(hash) != 64 || hash ~ /[^0-9a-fA-F]/ || size !~ /^[0-9]+$/) exit 1; print tolower(hash),size}
    ' "$1"
}
check_digest() {
    local file=$1 hash=$2 size=${3:-}
    [[ $hash =~ ^[0-9a-fA-F]{64}$ ]] || return 1
    [[ -z $size || $(stat -c %s "$file") == "$size" ]] || return 1
    [[ $(sha256sum "$file" | cut -d' ' -f1) == "${hash,,}" ]]
}
authenticate() {
    local url=$1 file=$2 rest base suite path digest hash size
    : > "$WORK/gpg-error"
    if [[ $url == */dists/* ]]; then
        base=${url%%/dists/*}; rest=${url#*/dists/}; suite=${rest%%/*}; path=${rest#*/}
        release_file "$base" "$suite" "$WORK/auth-release" || return 1
        digest=$(release_digest "$WORK/auth-release" "$path") || return 1
        read -r hash size <<< "$digest"
        check_digest "$file" "$hash" "$size"
    else
        fetch "$url.sign" "$WORK/detached.sig" 1048576 || fetch "$url.gpg" "$WORK/detached.sig" 1048576 || return 1
        keyring_args
        gpgv "${KeyringArgs[@]}" "$WORK/detached.sig" "$file" 2>"$WORK/gpg-error"
    fi
}
official_debian_mirror() {
    case $1 in
        https://deb.debian.org/debian/*|https://cdn-aws.deb.debian.org/debian/*|https://ftp.debian.org/debian/*|https://archive.debian.org/debian/*) return 0;;
        *) return 1;;
    esac
}
missing_archive_key() {
    [[ -s $WORK/gpg-error ]] || return 1
    grep -Eiq 'NO_PUBKEY|no public key|public key not found' "$WORK/gpg-error"
}
mirrors() {
    Mirrors=()
    [[ -z $Mirror ]] || Mirrors+=("${Mirror%/}")
    Mirrors+=(https://deb.debian.org/debian https://cdn-aws.deb.debian.org/debian https://ftp.debian.org/debian https://archive.debian.org/debian)
}
resolve_suite() {
    local base code version input=${Suite,,}
    if [[ -z $input || $input == stable ]]; then
        if (( DryRun )); then input=13
        else
            for base in "${Mirrors[@]}"; do
                if release_file "$base" stable "$WORK/stable-release"; then
                    code=$(sed -n 's/^Codename: *//p' "$WORK/stable-release")
                    version=$(sed -n 's/^Version: *//p' "$WORK/stable-release"); version=${version%%.*}
                    [[ $code =~ ^[a-z]{3,20}$ && $version =~ ^[0-9]{1,3}$ ]] || continue
                    case $code in stable|testing|unstable|sid|bullseye) continue;; esac
                    (( 10#$version >= 12 )) || continue
                    Suite=$code; ReleaseNumber=$((10#$version))
                    return 0
                fi
            done
            die 'Cannot authenticate and resolve stable metadata; specify --version 12 or 13, or update the keyring'
        fi
    fi
    case $input in
        12|bookworm) Suite=bookworm; ReleaseNumber=12;;
        13|trixie) Suite=trixie; ReleaseNumber=13;;
        *) die "Unsupported Debian release: $input (use 12, 13 or stable)";;
    esac
}
installer_download_set() {
    local directory=$1
    shift
    local base parent url prefix name entry hash index complete found=0 authenticated
    local names=("$@") urls=() hashes=()
    mkdir -p -- "$directory"
    for base in "${DownloadBases[@]}"; do
        urls=(); prefix=; authenticated=0
        if [[ $base == */netboot/* ]]; then
            parent=${base%%/netboot/*}; prefix=${base#"$parent"/}
            urls+=("$parent/SHA256SUMS")
        else
            urls+=("$base/SHA256SUMS")
        fi
        hashes=()
        for url in "${urls[@]}"; do
            fetch "$url" "$WORK/SHA256SUMS" 1048576 || continue
            if authenticate "$url" "$WORK/SHA256SUMS"; then
                authenticated=1
            elif official_debian_mirror "$base" && missing_archive_key; then
                message "Archive signing key is unavailable; using HTTPS SHA-256 manifest from $url"
            else
                continue
            fi
            hashes=()
            for name in "${names[@]}"; do
                entry=$name
                [[ $url == "$base/SHA256SUMS" ]] || entry=$prefix/$name
                hash=$(awk -v want="$entry" '{p=$2; sub(/^\*/,"",p); sub(/^\.\//,"",p); if(p==want) {n++; h=$1}} END {if(n==1 && length(h)==64 && h !~ /[^a-fA-F0-9]/) print tolower(h)}' "$WORK/SHA256SUMS")
                [[ -n $hash ]] || break
                hashes+=("$hash")
            done
            (( ${#hashes[@]} != ${#names[@]} )) || break
        done
        if (( ${#hashes[@]} != ${#names[@]} )); then
            message "No complete SHA-256 set at $base; trying next mirror"; continue
        fi
        (( authenticated )) || message 'Warning: installer manifest was not GPG-authenticated; HTTPS and per-file SHA-256 checks passed.'
        # Read one manifest before downloading; retry the whole set on a new mirror.
        complete=1
        for index in "${!names[@]}"; do
            name=${names[index]}
            if ! fetch "$base/$name" "$directory/$name.part" 536870912; then complete=0; break; fi
            check_digest "$directory/$name.part" "${hashes[index]}" || die "SHA-256 mismatch: $name"
        done
        (( complete )) || continue
        for name in "${names[@]}"; do mv -f -- "$directory/$name.part" "$directory/$name"; done
        DownloadMirror=$base; found=1; break
    done
    (( found )) || die "No usable mirror for ${names[*]}"
}
installer_download() {
    local name=$1 output=$2
    installer_download_set "$WORK/download" "$name"
    mv -f -- "$WORK/download/$name" "$output"
}

inject_udebs() {
    local base path="main/debian-installer/binary-$Arch/Packages.gz" index_ok=0
    for base in "$SelectedMirror" https://deb.debian.org/debian; do
        fetch "$base/dists/$Suite/$path" "$WORK/Packages.gz" || continue
        authenticate "$base/dists/$Suite/$path" "$WORK/Packages.gz" || continue
        gzip -dc "$WORK/Packages.gz" > "$WORK/Packages" || continue
        index_ok=1; break
    done
    (( index_ok )) || die 'Cannot authenticate the installer package index'
    # Produce a dependency closure, selecting the first available alternative.
    awk '
      BEGIN {RS=""; FS="\n"}
      {name=""; file=""; hash=""; deps=""; field=""
       for(i=1;i<=NF;i++) {
         line=$i
         if(line ~ /^[ \t]/) {if(field=="Depends") deps=deps " " line; continue}
         split(line,x,": "); field=x[1]; sub(/^[^:]+: */,"",line)
         if(field=="Package") name=line
         if(field=="Filename") file=line
         if(field=="SHA256") hash=line
         if(field=="Depends") deps=line
       }
       if(name!="" && file!="") {files[name]=file; hashes[name]=hash; depends[name]=deps}}
      END {
       queue[1]="openssh-server-udeb"; queue[2]="screen-udeb"; end=2
       for(q=1;q<=end;q++) {
         p=queue[q]; if(seen[p]++) continue
         if(!(p in files)) {if(q<=2) exit 1; continue}
         print p "\t" files[p] "\t" hashes[p]
         n=split(depends[p],groups,",")
         for(i=1;i<=n;i++) {m=split(groups[i],alts,"|")
           for(j=1;j<=m;j++) {a=alts[j]; sub(/^[ \t]+/,"",a); sub(/[ (:].*$/,"",a)
             if(a in files) {queue[++end]=a; break}}}
       }
      }' "$WORK/Packages" > "$WORK/closure" || die 'Installer SSH packages unavailable'
    local package filename hash entry target
    mkdir -p "$WORK/udeb"
    while IFS=$'\t' read -r package filename hash; do
        [[ $filename == pool/* && $filename != *..* ]] || die 'Invalid installer package path'
        [[ $hash =~ ^[0-9a-fA-F]{64}$ ]] || die "Missing or invalid package checksum: $package"
        fetch "$base/$filename" "$WORK/package.udeb" || die "Cannot download $package"
        check_digest "$WORK/package.udeb" "$hash" || die "Package checksum mismatch: $package"
        # Extract in isolation, then merge only names absent from the original initrd.
        rm -rf -- "$WORK/udeb"; mkdir "$WORK/udeb"
        dpkg-deb -x "$WORK/package.udeb" "$WORK/udeb"
        while IFS= read -r -d '' entry; do
            target=$InitrdRoot/${entry#"$WORK/udeb/"}
            [[ ! -e $target && ! -L $target ]] || continue
            # Follow merged-/usr links only when they stay inside the unpacked initrd.
            target=$(realpath -m -- "$target")
            [[ $target == "$InitrdRoot/"* ]] || die "Symlink escapes installer payload: $target"
            if [[ -d $entry && ! -L $entry ]]; then mkdir -p -- "$target"; chmod --reference="$entry" "$target"
            else mkdir -p -- "${target%/*}"; cp -a -- "$entry" "$target"; fi
        done < <(find "$WORK/udeb" -mindepth 1 -print0 | sort -z)
    done < "$WORK/closure"
}

detect_arch() {
    Arch=$(dpkg --print-architecture 2>/dev/null || uname -m)
    case $Arch in x86_64|amd64) Arch=amd64;; aarch64|arm64) Arch=arm64;; *) die "Unsupported architecture: $Arch";; esac
    if (( CloudKernel )); then Kernel=linux-image-cloud-$Arch; else Kernel=linux-image-$Arch; fi
}
detect_disk() {
    local candidates=() dev type label
    RootDevice=$(findmnt -nro SOURCE / 2>/dev/null || true); RootDevice=${RootDevice%%\[*}
    if [[ -z $Disk ]]; then
        while read -r dev type; do [[ $type != disk ]] || candidates+=("$dev"); done < <(lsblk -sprno NAME,TYPE "$RootDevice" 2>/dev/null | sort -u)
        if (( ${#candidates[@]} == 1 )); then Disk=${candidates[0]}
        elif (( DryRun )); then Disk='/dev/sda'; message 'Preview: disk detection unavailable; /dev/sda is an example'
        else die 'Cannot identify one root disk; specify --disk'; fi
    fi
    [[ $Disk =~ ^/dev/[a-zA-Z0-9_./-]+$ ]] || die 'Invalid detected disk'
    if (( !DryRun )); then
        [[ -b $Disk ]] || die "Not a block device: $Disk"
        [[ $(lsblk -dnro TYPE "$Disk") == disk ]] || die '--disk must name a whole physical or virtual disk'
    fi
    label=$(lsblk -dnro PTTYPE "$Disk" 2>/dev/null || true)
    case $label in dos|msdos) DiskLabel=msdos;; gpt|'') DiskLabel=gpt;; *) die "Unsupported partition table: $label";; esac
    EFI=0
    if [[ -d /sys/firmware/efi ]]; then EFI=1; fi
    if (( EFI )) && [[ $DiskLabel != gpt ]]; then
        (( ${#KeepPaths[@]} == 0 )) || die 'UEFI partition preservation requires GPT'
        DiskLabel=gpt
    fi
    DiskID=$(lsblk -dnro PTUUID "$Disk" 2>/dev/null | tr 'A-F' 'a-f' | tr -d '{} ' || true); DiskID=${DiskID#0x}
    RootPartUUID=$(lsblk -rno TYPE,PARTUUID "$Disk" 2>/dev/null | awk '$1=="part" && NF==2 {print $2; exit}' || true)
    [[ -z $DiskID || $DiskID =~ ^[a-f0-9-]+$ ]] || die 'Invalid disk identifier'
    [[ -z $RootPartUUID || $RootPartUUID =~ ^[a-fA-F0-9-]+$ ]] || die 'Invalid partition identifier'
    if (( SystemSizeMB && !DryRun )); then
        local bytes overhead=5
        (( !EFI )) || overhead=$((ESPSize+4))
        bytes=$(lsblk -bdnro SIZE "$Disk")
        (( bytes >= (SystemSizeMB+overhead)*1000000 )) || die '--system-size exceeds disk capacity'
    fi
}
preserve_partitions() {
    (( ${#KeepPaths[@]} > 0 )) || return 0
    local dev type fs uuid mount num data_index=0 pass path found row
    local rows=() root_chain
    root_chain=$(lsblk -sprno NAME "$RootDevice" 2>/dev/null || true)
    while read -r dev type fs uuid mount; do
        [[ $type == part ]] || continue
        # Read columns independently so missing values cannot shift fields.
        fs=$(lsblk -dnro FSTYPE "$dev"); uuid=$(lsblk -dnro PARTUUID "$dev"); mount=$(lsblk -dnro MOUNTPOINT "$dev")
        rows+=("$dev|$fs|$uuid|$mount")
    done < <(lsblk -prno NAME,TYPE "$Disk")
    for path in "${KeepPaths[@]}"; do
        found=0
        for row in "${rows[@]}"; do
            IFS='|' read -r dev fs uuid mount <<< "$row"
            [[ $dev == "$path" ]] || continue
            found=1
            [[ $dev != "$RootDevice" && -n $fs && $fs != swap ]] || die "Cannot preserve root/swap/unknown filesystem: $dev"
            ! grep -Fxq "$dev" <<< "$root_chain" || die "Cannot preserve a root filesystem ancestor: $dev"
            case $mount in /|/boot|/boot/efi|/usr|/var|/etc|/tmp) die "Cannot preserve system mount: $dev ($mount)";; esac
            num=${dev##*[!0-9]}; [[ $num =~ ^[0-9]+$ ]] || die "Unknown partition number: $dev"
            [[ $DiskLabel != msdos || $num -le 4 ]] || die 'Cannot preserve logical partitions on an msdos disk'
            KeepParts+=("$num")
            case $fs in
                ext2|ext3|ext4|xfs|btrfs)
                    [[ $uuid =~ ^[a-fA-F0-9-]+$ ]] || die "Missing PARTUUID: $dev"
                    ((data_index+=1)); mount=/data; (( data_index == 1 )) || mount=/data$data_index
                    pass=2; [[ $fs != btrfs ]] || pass=0
                    KeepFstab+=("$uuid|$mount|$fs|$pass");;
            esac
            message "Preserve $dev ($fs)"; break
        done
        (( found )) || die "Partition $path does not belong to $Disk"
    done
    message 'Preservation uses the largest free region; all unpreserved partitions may be deleted.'
}

route_field() { awk -v name="$1" '{for(i=1;i<NF;i++) if($i==name) {print $(i+1); exit}}'; }
read_system_dns() {
    awk '$1=="nameserver" {
        address=tolower($2)
        if (address !~ /^127\./ && address != "::1" && address != "100.100.100.100" && address != "fd7a:115c:a1e0::53") printf "%s ", $2
    }' "${1:-/etc/resolv.conf}" 2>/dev/null || true
}
detect_network() {
    local route4 route6 addr4 addr6 dynamic4=0 dynamic6=0 configured='' detected_gateway dns v6_mode=auto
    route4=$(ip -4 route show default 2>/dev/null | head -n1 || true)
    route6=$(ip -6 route show default 2>/dev/null | head -n1 || true)
    if [[ $Interface == auto ]]; then
        Interface=$(printf '%s\n%s\n' "$route4" "$route6" | route_field dev)
        [[ -n $Interface ]] || Interface=$(ip -o link show up 2>/dev/null | awk -F': ' '$2!="lo" {sub(/@.*/,"",$2); print $2; exit}' || true)
    fi
    if [[ -z $Interface ]]; then
        (( DryRun )) || die 'Cannot detect network interface; specify --interface'
        Interface=eth0; message 'Preview: network detection unavailable; eth0 is an example'
    fi
    [[ $Interface =~ ^[a-zA-Z0-9_.:-]{1,15}$ ]] || die 'Invalid detected interface name'
    if [[ $(printf '%s\n' "$route4" | route_field dev) != "$Interface" ]]; then
        route4=$(ip -4 route show default dev "$Interface" 2>/dev/null | head -n1 || true)
    fi
    addr4=$(ip -o -4 addr show dev "$Interface" scope global 2>/dev/null | head -n1 || true)
    local v6_interface
    v6_interface=$(printf '%s\n' "$route6" | route_field dev)
    v6_interface=${v6_interface:-$Interface}
    [[ -z $IPv6 ]] || v6_interface=$Interface
    [[ $v6_interface =~ ^[a-zA-Z0-9_.:-]{1,15}$ ]] || die 'Invalid detected IPv6 interface'
    addr6=$(ip -o -6 addr show dev "$v6_interface" scope global 2>/dev/null | awk '!/ temporary / && !/ tentative / && !/ deprecated / {print; exit}' || true)
    [[ $addr4 != *' dynamic '* && $route4 != *' proto dhcp '* ]] || dynamic4=1
    [[ $addr6 != *' dynamic '* && $addr6 != *' mngtmpaddr '* && $route6 != *' proto ra '* ]] || dynamic6=1
    # ifupdown can retain a DHCP lease without the kernel dynamic flag.
    if command -v ifquery >/dev/null 2>&1; then configured=$(ifquery "$Interface" 2>/dev/null || true); fi
    [[ $configured != *'inet dhcp'* ]] || dynamic4=1
    if [[ $configured == *'inet6 dhcp'* ]] && (( ReleaseNumber < 13 )); then v6_mode=dhcp; fi
    detected_gateway=
    if [[ $(printf '%s\n' "$route4" | route_field dev) == "$Interface" ]]; then
        detected_gateway=$(printf '%s\n' "$route4" | route_field via)
    fi
    if [[ -n $IP ]]; then
        Static=1; [[ -n $Netmask ]] || Netmask=255.255.255.0; IPPrefix=$(mask_prefix "$Netmask")
    elif [[ -n $addr4 ]]; then
        IP=$(awk '{print $4}' <<< "$addr4"); IPPrefix=${IP#*/}; IP=${IP%/*}
        (( dynamic4 )) || Static=1
        Netmask=$(prefix_mask "$IPPrefix")
    fi
    [[ -n $Gateway ]] || Gateway=$detected_gateway
    [[ -n $IP ]] || Static=0
    if [[ -n $IPv6 ]]; then
        InstallerV6Address=${IPv6%/*}; InstallerV6Prefix=64
        [[ $IPv6 != */* ]] || InstallerV6Prefix=$((10#${IPv6##*/}))
        InstallerV6Interface=$Interface
    elif [[ -n $addr6 && $dynamic6 == 0 ]]; then
        IPv6=$(awk '{print $4}' <<< "$addr6"); InstallerV6Address=${IPv6%/*}; InstallerV6Prefix=${IPv6#*/}; InstallerV6Interface=$v6_interface
    fi
    InstallerV6Gateway=${IPv6Gateway:-$(printf '%s\n' "$route6" | route_field via)}
    InstallerV6Gateway=${InstallerV6Gateway%%%*}
    if (( !DNSExplicit )); then
        DNS=$(read_system_dns /etc/resolv.conf)
        if [[ -z $DNS ]]; then
            DNS='1.1.1.1 8.8.8.8'
        fi
    fi
    DNS="${DNS}${IPv6DNS:+ $IPv6DNS}"
    if [[ -z $IP && -n $IPv6 && $DNSExplicit == 0 && -z $IPv6DNS ]]; then DNS='2606:4700:4700::1111 2001:4860:4860::8888'; fi
    for dns in $DNS; do ipv4_number "$dns" >/dev/null || valid_ipv6 "$dns" || die "Invalid detected DNS: $dns"; done
    if (( Static )); then
        ipv4_number "$IP" >/dev/null || die 'Invalid detected IPv4'
        if [[ -n $Gateway ]]; then
            local ipnum gatewaynum mask
            ipnum=$(ipv4_number "$IP"); gatewaynum=$(ipv4_number "$Gateway") || die 'Invalid detected gateway'; mask=$(ipv4_number "$Netmask")
            (( (ipnum & mask) == (gatewaynum & mask) )) || InstallerOnlink=1
        fi
    fi
    [[ -n $IP || -z $InstallerV6Address ]] || InstallerOnlink=1
    if [[ -n $InstallerV6Address ]]; then
        valid_ipv6 "$InstallerV6Address" || die 'Invalid detected IPv6'
        [[ -z $InstallerV6Gateway ]] || valid_ipv6 "$InstallerV6Gateway" || die 'Invalid detected IPv6 gateway'
    fi
    Hostname=$(printf '%s' "${Hostname:-$(hostname)}" | tr '[:upper:]' '[:lower:]' | sed 's/[^a-z0-9-]/-/g;s/^-*//;s/-*$//' | cut -c1-63)
    Hostname=${Hostname:-localhost}
    Interfaces=$(render_interfaces)$'\n'
    ResolvConf=$(for dns in $DNS; do printf 'nameserver %s\n' "$dns"; done)$'\n'
}
render_interfaces() {
    printf 'source /etc/network/interfaces.d/*\nauto lo\niface lo inet loopback\n\n'
    local mac='' v6_iface=${InstallerV6Interface:-${v6_interface:-$Interface}}
    [[ ! -r /sys/class/net/$Interface/address ]] || mac=$(cat "/sys/class/net/$Interface/address")
    [[ -z $mac ]] || printf '# mac %s\n' "$mac"
    printf 'auto %s\n' "$Interface"
    if [[ -n $IP ]]; then
        if (( Static )); then
            printf 'iface %s inet static\n    address %s/%s\n' "$Interface" "$IP" "$IPPrefix"
            if [[ -n $Gateway ]]; then
                if (( InstallerOnlink )); then
                    printf '    post-up ip -4 route replace %s/32 dev %s\n    post-up ip -4 route replace default via %s dev %s onlink\n' "$Gateway" "$Interface" "$Gateway" "$Interface"
                else printf '    gateway %s\n' "$Gateway"; fi
            fi
        else printf 'iface %s inet dhcp\n' "$Interface"; fi
    fi
    [[ -z $DNS || -z $IP ]] || printf '    dns-nameservers %s\n' "$DNS"
    if [[ $v6_iface != "$Interface" && ( -n $InstallerV6Address || -n ${addr6:-} ) ]]; then
        mac=
        [[ ! -r /sys/class/net/$v6_iface/address ]] || mac=$(cat "/sys/class/net/$v6_iface/address")
        [[ -z $mac ]] || printf '\n# mac %s\n' "$mac"
        printf 'auto %s\n' "$v6_iface"
    fi
    if [[ -n $InstallerV6Address ]]; then
        printf '\niface %s inet6 static\n    address %s/%s\n    pre-up sysctl -w net.ipv6.conf.%s.accept_ra=0\n    pre-up sysctl -w net.ipv6.conf.%s.autoconf=0\n' "$v6_iface" "$InstallerV6Address" "$InstallerV6Prefix" "$v6_iface" "$v6_iface"
        if [[ -n $InstallerV6Gateway ]]; then
            printf '    post-up ip -6 route replace %s/128 dev %s\n    post-up ip -6 route replace default via %s dev %s onlink\n' "$InstallerV6Gateway" "$v6_iface" "$InstallerV6Gateway" "$v6_iface"
        fi
    elif [[ -n ${addr6:-} ]]; then
        printf '\niface %s inet6 %s\n    accept_ra 2\n' "$v6_iface" "${v6_mode:-auto}"
    fi
    if [[ -n $InstallerV6Address || -n ${addr6:-} ]]; then [[ -z $DNS ]] || printf '    dns-nameservers %s\n' "$DNS"; fi
}

environment_check() {
    (( EUID == 0 )) || die 'Root privileges required'
    [[ $(uname -s) == Linux ]] || die 'Preparation requires Linux'
    [[ -f /etc/debian_version ]] || die 'Preparation requires Debian'
    [[ -f /etc/grub.d/40_custom ]] || die 'GRUB2 /etc/grub.d/40_custom not found'
    local virt=none code=0 secure mem tool
    if command -v systemd-detect-virt >/dev/null 2>&1; then virt=$(systemd-detect-virt) || code=$?; fi
    if (( Firmware )); then
        need systemd-detect-virt
        [[ $virt == none && $code == 1 ]] || die '--firmware requires confirmed physical hardware'
    fi
    [[ ! -e /.dockerenv && ! -e /run/.containerenv ]] || die 'Cannot prepare a container'
    case $virt in docker|lxc*|podman|systemd-nspawn|openvz) die 'Cannot prepare a container';; esac
    ! grep -qi microsoft /proc/version || die 'WSL preparation is unsupported'
    for secure in /sys/firmware/efi/efivars/SecureBoot-*; do
        [[ -f $secure ]] || continue
        [[ $(od -An -tu1 -j4 -N1 "$secure" | tr -d ' ') != 1 ]] || die 'Disable Secure Boot before preparing'
    done
    mem=$(awk '/^MemTotal:/ {print int($2/1024)}' /proc/meminfo)
    (( mem >= 384 )) || die 'At least 384 MB RAM required'
    for tool in curl gzip cpio dpkg-deb ip lsblk findmnt blkid sha256sum openssl awk sed find sort stat flock grub-mkrelpath grub-probe grub-reboot update-grub; do need "$tool"; done
    need gpgv; [[ -r ${Keyring:-/usr/share/keyrings/debian-archive-keyring.gpg} ]] || die 'Trusted Debian keyring missing'
    [[ -z $AuthorizedKeysURL ]] || need ssh-keygen
    if (( Firmware )) && [[ -z $Keyring ]]; then [[ -r /usr/share/keyrings/debian-role-keys.gpg ]] || die 'Firmware verification needs debian-keyring'; fi
}

# Completion output goes straight to the terminal, never through the log writer.
banner_row() {
    printf '  %s%-12s%s %s\n' "$BannerDim" "$1" "$BannerReset" "$2"
}
completion_banner() {
    local BannerAccent='' BannerSuccess='' BannerDim='' BannerReset='' BannerWarn=''
    if [[ -t 1 && ${TERM:-dumb} != dumb && ! ${NO_COLOR+x} ]]; then
        BannerAccent=$'\033[1;36m'; BannerSuccess=$'\033[1;32m'
        BannerDim=$'\033[2m'; BannerReset=$'\033[0m'; BannerWarn=$'\033[1;33m'
    fi
    local boot=BIOS target='' server='' root_size='available space'
    local network_sysfs=${NetworkSysfs:-/sys/class/net} mac4='' mac6='' iface6=${InstallerV6Interface:-$Interface}
    [[ ! -r $network_sysfs/$Interface/address ]] || mac4=$(<"$network_sysfs/$Interface/address")
    [[ ! -r $network_sysfs/$iface6/address ]] || mac6=$(<"$network_sysfs/$iface6/address")
    (( !EFI )) || boot=UEFI
    case $Suite in bookworm) target='Debian 12 (bookworm)';; trixie) target='Debian 13 (trixie)';; *) target="Debian $ReleaseNumber ($Suite)";; esac
    [[ -z $SystemSize ]] || root_size=$SystemSize
    printf '\n  %sreos%s  %sv%s%s\n' "$BannerAccent" "$BannerReset" "$BannerDim" "$PROGRAM_VERSION" "$BannerReset"
    printf '  %s------------------------------------------------------------%s\n' "$BannerDim" "$BannerReset"
    printf '  %sREADY TO REINSTALL%s\n' "$BannerSuccess" "$BannerReset"
    printf '  Preparation complete. Debian installation starts on reboot.\n\n'
    banner_row System "$target / $Arch"
    banner_row Disk "$Disk / ext4 / $boot"
    banner_row 'Root size' "$root_size"
    banner_row Hostname "$Hostname"
    banner_row Timezone "$Timezone"
    if (( ${#KeepPaths[@]} )); then banner_row Preserve "${KeepPaths[*]}"; fi
    printf '\n  %sACCESS%s\n' "$BannerAccent" "$BannerReset"
    banner_row User "$Username"
    banner_row 'SSH port' "$SSHPort"
    if [[ -n $AuthorizedKeys ]]; then
        banner_row Auth 'SSH public key (SSH password login disabled)'
    else
        banner_row Password "$Password"
        printf '  %sSave this password now; it is not written to the log.%s\n' "$BannerWarn" "$BannerReset"
    fi
    if [[ -n $IP ]]; then
        banner_row IPv4 "$IP"
        [[ -z $Gateway ]] || banner_row 'IPv4 gateway' "$Gateway"
        [[ -z $mac4 ]] || banner_row 'IPv4 MAC' "$mac4 ($Interface)"
        server=$IP
    fi
    if [[ -n $IPv6 ]]; then
        banner_row IPv6 "${IPv6%/*}"
        [[ -z $InstallerV6Gateway ]] || banner_row 'IPv6 gateway' "$InstallerV6Gateway"
        if [[ -n $mac6 ]]; then banner_row 'IPv6 MAC' "$mac6 ($iface6)"; fi
        [[ -n $server ]] || server=${IPv6%/*}
    fi
    if [[ -n $server ]]; then
        banner_row Connect "ssh -p $SSHPort $Username@$server"
        printf '  %sUses the configured address; keep any NAT/forwarding in mind.%s\n' "$BannerDim" "$BannerReset"
    else banner_row Connect "ssh -p $SSHPort $Username@SERVER_IP"; fi
    if (( InstallerSSH )); then
        banner_row Installer 'SSH enabled; same account and port'
        banner_row Progress 'tail -fn+1 /var/log/syslog (in installer SSH)'
    else banner_row Installer 'SSH disabled; use the server console'; fi
    printf '\n  %sNEXT%s\n' "$BannerAccent" "$BannerReset"
    if (( RebootNow )); then banner_row Action 'Rebooting automatically (--reboot-now)'
    else banner_row Start 'reboot'; banner_row Cancel 'reos reset (before reboot)'; fi
    printf '\n  %sThe next boot erases the current system on %s.%s\n' "$BannerWarn" "$Disk" "$BannerReset"
    printf '  %s------------------------------------------------------------%s\n\n' "$BannerDim" "$BannerReset"
}

read_local() {
    [[ -f $1 && ! -L $1 ]] || die "Expected a regular file without a symlink: $1"
    [[ $(stat -c %s "$1") -le 1048576 ]] || die "File exceeds 1 MiB: $1"
    cat -- "$1"
}
prepare_keys() {
    local line count=0
    fetch "$AuthorizedKeysURL" "$WORK/keys.download" 1048576 || die 'Cannot download authorized keys'
    sed 's/\r$//' "$WORK/keys.download" > "$WORK/keys"
    while IFS= read -r line || [[ -n $line ]]; do
        [[ $line =~ ^[[:space:]]*(#|$) ]] && continue
        [[ $line =~ ^[[:space:]]*(ssh-ed25519|ssh-rsa|ecdsa-sha2-nistp(256|384|521)|sk-ssh-ed25519@openssh.com|sk-ecdsa-sha2-nistp256@openssh.com)[[:space:]] ]] || die 'Expected an OpenSSH public key without authorized_keys options'
        printf '%s\n' "$line" > "$WORK/key-line"
        ssh-keygen -l -f "$WORK/key-line" >/dev/null 2>&1 || die 'Invalid SSH public key in authorized keys'
        ((count+=1))
    done < "$WORK/keys"
    (( count )) || die 'Authorized keys contain no SSH public keys'
    AuthorizedKeys=$(cat "$WORK/keys")
    KeysB64=$(base64 -w0 "$WORK/keys")
}
configure_payload() {
    local base=${SelectedMirror:-${Mirror:-https://deb.debian.org/debian}} rest
    AptProxy=$Proxy
    # APT only supports SOCKS with remote name resolution.
    [[ $AptProxy != socks5://* ]] || AptProxy=socks5h://${AptProxy#socks5://}
    MirrorProtocol=${base%%://*}; rest=${base#*://}; MirrorHost=${rest%%/*}
    MirrorDir=/${rest#*/}; [[ $rest == */* ]] || MirrorDir=/debian
    # Debian security archives have an independent layout from package mirrors.
    SecurityRepo=https://deb.debian.org/debian-security
    SecuritySuite=$Suite-security
    Install="$Install ifupdown"
    [[ $Username == root ]] || Install+=' sudo'
    (( !Unattended )) || Install+=' unattended-upgrades'
    Home=/root; [[ $Username == root ]] || Home=/home/$Username
    local mem
    mem=$(awk '/^MemTotal:/ {print int($2/1024)}' /proc/meminfo 2>/dev/null || true)
    if [[ -n $mem ]] && (( mem > 0 && mem < 1024 )); then Swap=1; fi
    [[ -n $SwapSize ]] || { SwapSize=1G; SwapMB=1024; }
}
write_payload() {
    local dir=$1
    mkdir -p "$dir/reos-assets" "$dir/configs"
    # The archive includes '.', which becomes / in the installer.
    # Keep it traversable for the configured non-root SSH account.
    chmod 755 "$dir"
    local assets=$dir/reos-assets
    asset_preseed_tmpl > "$dir/preseed.cfg"
    asset_late_sh_tmpl > "$assets/late.sh"
    asset_firstboot_firstboot_sh_tmpl > "$assets/firstboot.sh"
    asset_firstboot_fix_eth_name_sh > "$assets/fix-eth-name.sh"
    asset_firstboot_fix_eth_name_service > "$assets/fix-eth-name.service"
    asset_installer_early_sh > "$assets/early.sh"
    asset_partman_partman_early_sh > "$assets/partman-early.sh"
    if (( InstallerOnlink )); then
        mkdir -p "$dir/var/lib/dpkg/info"
        asset_installer_netcfg_onlink_sh_tmpl > "$dir/var/lib/dpkg/info/netcfg.postinst"
        chmod 755 "$dir/var/lib/dpkg/info/netcfg.postinst"
    fi
    (( !SystemSizeMB )) || : > "$assets/system-size"
    if [[ -n $SecurityRepo ]]; then asset_installer_post_base_installer_sh_tmpl > "$assets/post-base-installer.sh"; fi
    asset_firstboot_cleanup_sh > "$assets/cleanup.sh"
    if (( InstallerSSH )); then
        asset_installer_ssh_installer_ssh_sh_tmpl > "$assets/installer-ssh.sh"
        printf '%s\n' "$PasswordHash" > "$dir/configs/reos-installer-pass"
        [[ -z $AuthorizedKeys ]] || printf '%s\n' "$AuthorizedKeys" > "$dir/configs/reos-installer-keys"
    fi
    if (( Optimize )); then
        mkdir -p "$assets/optimize"
        asset_optimize_10_sysctl_sh > "$assets/optimize/10-sysctl.sh"
        asset_optimize_20_limits_sh > "$assets/optimize/20-limits.sh"
        asset_optimize_30_journald_sh > "$assets/optimize/30-journald.sh"
        asset_optimize_40_logrotate_sh > "$assets/optimize/40-logrotate.sh"
    fi
    find "$assets" -name '*.sh' -exec chmod 755 {} +
    chmod 644 "$assets/fix-eth-name.service" "$dir/preseed.cfg"
}
summary() {
    message "reos $PROGRAM_VERSION — Debian $Suite ($Arch)"
    message "Disk: $Disk; label: $DiskLabel; filesystem: ext4; EFI: $EFI"
    message "Network: $Interface; IPv4: ${IP:-none}; static: $Static; IPv6: ${IPv6:-auto/none}"
    message "Hostname: $Hostname; timezone: $Timezone; kernel: $Kernel"
    message "Login: $Username; SSH port: $SSHPort; installer SSH: $InstallerSSH"
    [[ -z $SystemSize ]] || message "Root size cap: $SystemSize"
    if (( ${#KeepParts[@]} )); then message "Preserved partitions: ${KeepParts[*]}"; fi
}
preview() {
    resolve_suite
    detect_arch
    detect_disk
    detect_network
    preserve_partitions
    configure_payload
    summary
    printf '\n# Target /etc/network/interfaces\n%s\n' "$Interfaces"
    printf '# Preseed preview (password hash omitted)\n'
    PasswordHash='!'
    asset_preseed_tmpl
    message 'Preview only: no downloads, dependency installation, or boot changes.'
}

strip_grub() { sed '/^### BEGIN reos ###$/,/^### END reos ###$/d' "$1"; }
COMMIT_STARTED=0
COMMITTED=0
BOOT_BACKUP=
BOOT_MOVED=0
commit_cleanup() {
    local code=$?
    if (( COMMIT_STARTED && !COMMITTED )); then
        printf 'reos: restoring previous boot configuration after preparation failure\n' >&2
        cp -p -- "$WORK/40_custom.backup" /etc/grub.d/40_custom || true
        if [[ -e $WORK/default.backup ]]; then cp -p -- "$WORK/default.backup" /etc/default/grub.d/zz-reos.cfg || true
        else rm -f /etc/default/grub.d/zz-reos.cfg; fi
        if (( BOOT_MOVED )); then
            rm -rf /boot/reos
            mv -- "$BOOT_BACKUP" /boot/reos || true
        elif [[ -f $WORK/no-previous-boot ]]; then rm -rf /boot/reos; fi
        local env
        for env in grub grub2; do
            [[ ! -f $WORK/$env.grubenv ]] || cp -p -- "$WORK/$env.grubenv" "/boot/$env/grubenv" || true
        done
        update-grub >/dev/null 2>&1 || true
    fi
    cleanup
    return "$code"
}
commit_boot() {
    local uuid boot_path linux_path initrd_path firmware_path='' env args keep
    uuid=$(grub-probe --target=fs_uuid /boot)
    [[ $uuid =~ ^[a-zA-Z0-9-]+$ ]] || die 'Cannot identify /boot filesystem for GRUB'
    # Probe the existing directory; installer files do not exist on the first run.
    boot_path=$(grub-mkrelpath /boot)
    linux_path=${boot_path%/}/reos/linux
    initrd_path=${boot_path%/}/reos/initrd.gz
    (( !Firmware )) || firmware_path=${boot_path%/}/reos/firmware.cpio.gz
    [[ $linux_path =~ ^/[a-zA-Z0-9/._-]+$ && $initrd_path =~ ^/[a-zA-Z0-9/._-]+$ ]] || die 'Invalid GRUB file paths'
    args="auto=true priority=critical preseed/file=/preseed.cfg reos_disk=$Disk"
    [[ -z $DiskID ]] || args+=" reos_disk_id=$DiskID"
    [[ -z $RootPartUUID ]] || args+=" reos_root_partuuid=$RootPartUUID"
    if (( ${#KeepParts[@]} )); then keep=$(IFS=,; printf '%s' "${KeepParts[*]}"); args+=" reos_keep=$keep"; fi
    cp -p /etc/grub.d/40_custom "$WORK/40_custom.backup"
    [[ ! -e /etc/default/grub.d/zz-reos.cfg ]] || cp -p /etc/default/grub.d/zz-reos.cfg "$WORK/default.backup"
    for env in grub grub2; do [[ ! -f /boot/$env/grubenv ]] || cp -p "/boot/$env/grubenv" "$WORK/$env.grubenv"; done
    strip_grub /etc/grub.d/40_custom > "$WORK/40_custom.new"
    cat >> "$WORK/40_custom.new" <<GRUB
### BEGIN reos ###
menuentry 'Debian Installer (reos)' --id reos {
    insmod part_msdos
    insmod part_gpt
    insmod ext2
    insmod xfs
    insmod btrfs
    search --no-floppy --fs-uuid --set=root $uuid
    linux $linux_path $args
    initrd $initrd_path $firmware_path
}
### END reos ###
GRUB
    trap commit_cleanup EXIT
    COMMIT_STARTED=1
    if [[ -e /boot/reos ]]; then
        BOOT_BACKUP=$(mktemp -d /boot/.reos-backup.XXXXXXXX)
        rmdir "$BOOT_BACKUP"
        mv /boot/reos "$BOOT_BACKUP"
        BOOT_MOVED=1
    else : > "$WORK/no-previous-boot"; fi
    mkdir -m700 /boot/reos
    install -m600 "$WORK/linux" /boot/reos/linux
    install -m600 "$WORK/final-initrd.gz" /boot/reos/initrd.gz
    (( !Firmware )) || install -m600 "$WORK/firmware.cpio.gz" /boot/reos/firmware.cpio.gz
    mkdir -p /etc/default/grub.d
    printf '# Added by reos\nGRUB_DEFAULT=saved\nGRUB_TIMEOUT=5\nGRUB_TIMEOUT_STYLE=menu\n' > /etc/default/grub.d/zz-reos.cfg
    chmod 644 /etc/default/grub.d/zz-reos.cfg
    install -m755 "$WORK/40_custom.new" /etc/grub.d/40_custom
    update-grub
    grub-reboot reos
    COMMITTED=1
    [[ -z $BOOT_BACKUP ]] || rm -rf -- "$BOOT_BACKUP"
}
prepare() {
    environment_check
    [[ ! -L /boot/reos ]] || die 'Refusing a symlink installer directory'
    exec 9>/run/lock/reos.lock
    flock -n 9 || die 'Another reos process is running'
    scratch
    [[ ! -L /var/log/reos.log ]] || die 'Refusing a symlink preparation log'
    touch /var/log/reos.log; chmod 600 /var/log/reos.log; LOG_ACTIVE=1
    mirrors
    resolve_suite
    detect_arch
    detect_disk
    detect_network
    preserve_partitions
    Password=${Password:-$(openssl rand -hex 12)}
    PasswordHash=$(printf '%s\n' "$Password" | openssl passwd -6 -stdin)
    if [[ -n $AuthorizedKeysURL ]]; then
        prepare_keys
    fi
    if [[ -n $PostInstall ]]; then
        case $PostInstall in
            http://*|https://*) fetch "$PostInstall" "$WORK/post-install" 1048576 || die 'Cannot fetch post-install script';;
            *) read_local "$PostInstall" > "$WORK/post-install";;
        esac
        PostInstallB64=$(base64 -w0 "$WORK/post-install")
    fi
    local base
    DownloadBases=()
    for base in "${Mirrors[@]}"; do DownloadBases+=("$base/dists/$Suite/main/installer-$Arch/current/images/netboot/debian-installer/$Arch"); done
    SelectedMirror=${Mirrors[0]}
    message 'Downloading and verifying installer kernel and initrd ...'
    installer_download_set "$WORK" linux initrd.gz
    # Use the authenticated installer mirror for the target package repository.
    SelectedMirror=${DownloadMirror%%/dists/*}
    if (( Firmware )); then
        local saved_bases=("${DownloadBases[@]}")
        DownloadBases=("https://cdimage.debian.org/cdimage/unofficial/non-free/firmware/$Suite/current")
        installer_download firmware.cpio.gz "$WORK/firmware.cpio.gz"
        DownloadBases=("${saved_bases[@]}")
    fi
    configure_payload
    InitrdRoot=$WORK/initrd
    mkdir "$InitrdRoot"
    # Signed Debian initrds contain relative archive names. Validate before extraction.
    gzip -dc "$WORK/initrd.gz" > "$WORK/initrd.cpio"
    cpio -it --quiet < "$WORK/initrd.cpio" > "$WORK/initrd.names"
    if grep -Eq '(^/|(^|/)\.\.(/|$))' "$WORK/initrd.names"; then die 'Unsafe path in installer initrd'; fi
    (cd "$InitrdRoot"; cpio -idmu --quiet --no-absolute-filenames < "$WORK/initrd.cpio")
    if (( InstallerSSH )); then message 'Preparing installer SSH components ...'; inject_udebs; fi
    # Payload lives in a separate archive appended after the original initrd.
    mkdir "$WORK/payload"
    write_payload "$WORK/payload"
    (cd "$InitrdRoot"; find . -print0 | cpio --null -o -H newc --quiet | gzip -1) > "$WORK/final-initrd.gz"
    (cd "$WORK/payload"; find . -print0 | cpio --null -o -H newc --quiet | gzip -1) >> "$WORK/final-initrd.gz"
    local needed available
    needed=$(du -ck "$WORK/linux" "$WORK/final-initrd.gz" "$WORK"/firmware.cpio.gz 2>/dev/null | tail -n1 | awk '{print $1}' || true)
    available=$(df -Pk /boot | awk 'END {print $4}')
    (( available > needed+10240 )) || die 'Insufficient free space in /boot'
    summary
    if (( !Yes )); then
        local answer=
        printf '\nNext boot will repartition %s and erase the current system. Continue? [y/N]: ' "$Disk"
        if ! read -r answer < /dev/tty; then die 'Confirmation needs a terminal; use --yes for unattended execution'; fi
        case ${answer,,} in y|yes) ;; *) message 'Canceled; boot configuration unchanged.'; return 0;; esac
    fi
    commit_boot
    message 'Preparation complete; one-time Debian installer boot configured.'
    completion_banner
    if (( RebootNow )); then sync; reboot; fi
}

status() {
    printf 'reos %s\n' "$PROGRAM_VERSION"
    local path env
    for path in /boot/reos/linux /boot/reos/initrd.gz /boot/reos/firmware.cpio.gz; do
        [[ ! -f $path ]] || printf 'Installer: %s (%s bytes)\n' "$path" "$(stat -c %s "$path")"
    done
    if grep -q '^### BEGIN reos ###$' /etc/grub.d/40_custom 2>/dev/null; then printf 'GRUB entry: installed\n'; else printf 'GRUB entry: not installed\n'; fi
    for env in /boot/grub/grubenv /boot/grub2/grubenv; do [[ ! -f $env ]] || grub-editenv "$env" list 2>/dev/null || true; done
    for path in /var/lib/reos/firstboot-status /var/lib/reos/cleanup-status; do [[ ! -f $path ]] || { printf '%s: ' "$path"; cat "$path"; }; done
}
logs() {
    local kind=${1:-reos} path paths=()
    case $kind in
        reos) paths=(/var/log/reos.log);;
        firstboot) paths=(/var/log/reos-firstboot.log);;
        cleanup) paths=(/var/log/reos-cleanup.log);;
        all) paths=(/var/log/reos.log /var/log/reos-firstboot.log /var/log/reos-cleanup.log);;
        *) die 'Unknown log type (reos/firstboot/cleanup/all)';;
    esac
    for path in "${paths[@]}"; do [[ ! -f $path ]] || { printf '==> %s <==\n' "$path"; tail -n80 "$path"; }; done
}
reset() {
    (( EUID == 0 )) || die 'Root privileges required'
    need update-grub; need grub-editenv; need flock
    exec 9>/run/lock/reos.lock; flock -n 9 || die 'Another reos process is running'
    scratch
    [[ ! -L /boot/reos ]] || die 'Refusing a symlink installer directory'
    if [[ -f /etc/grub.d/40_custom ]]; then
        strip_grub /etc/grub.d/40_custom > "$WORK/custom"
        install -m755 "$WORK/custom" /etc/grub.d/40_custom
    fi
    rm -f /etc/default/grub.d/zz-reos.cfg
    local env next
    for env in /boot/grub/grubenv /boot/grub2/grubenv; do
        [[ -f $env ]] || continue
        next=$(grub-editenv "$env" list | sed -n 's/^next_entry=//p')
        case $next in reos|'Debian Installer (reos)') grub-editenv "$env" unset next_entry;; esac
    done
    update-grub
    rm -rf /boot/reos
    message 'Reinstallation canceled; installer entry and files removed.'
}
main() {
    (( BASH_VERSINFO[0] >= 4 )) || die 'Bash 4 or newer required'
    defaults
    case ${1:-} in
        status) (( $# == 1 )) || die 'status takes no arguments'; status; return;;
        logs) (( $# <= 2 )) || die 'logs accepts one log type'; logs "${2:-reos}"; return;;
        reset) (( $# == 1 )) || die 'reset takes no arguments'; reset; return;;
    esac
    parse "$@"
    validate
    if (( DryRun )); then preview; else prepare; fi
}

