asset_firstboot_fix_eth_name_sh() {
cat <<'REOS_EMBEDDED_ASSET'
#!/bin/bash
# Generated by reos.
set -eu

IFACES=/etc/network/interfaces
SYSFS=/sys/class/net

[ -f "$IFACES" ] || exit 0

log() { echo "fix-eth-name: $*" >&2; }

list_devs() {
    ls "$SYSFS" 2>/dev/null | grep -vx 'lo' || true
}

old=
stable=0
waited=0
while :; do
    cur=$(list_devs)
    if [ -n "$cur" ] && [ "$old" = "$cur" ]; then
        stable=$((stable + 1))
    else
        stable=0
    fi
    old=$cur
    if [ -n "$cur" ] && [ "$stable" -ge 10 ]; then
        break
    fi
    if [ -z "$cur" ] && [ "$waited" -ge 60 ]; then
        log "No network interface appeared within 60 seconds; giving up"
        exit 1
    fi
    waited=$((waited + 1))
    sleep 1
done

get_ethx_by_mac() {
    want=$(printf '%s' "$1" | tr '[:upper:]' '[:lower:]')
    [ -n "$want" ] || return 1
    for dev in $(list_devs); do
        if [ -e "$SYSFS/$dev/master" ]; then
            continue
        fi
        if [ ! -r "$SYSFS/$dev/address" ]; then
            continue
        fi
        addr=$(tr '[:upper:]' '[:lower:]' <"$SYSFS/$dev/address")
        if [ "$addr" = "$want" ]; then
            printf '%s' "$dev"
            return 0
        fi
    done
    return 1
}

tmp=$IFACES.reos-tmp
rm -f "$tmp"

ethx=
while IFS= read -r line || [ -n "$line" ]; do
    keep=1
    case "$line" in
    '# mac '*)
        mac=${line#'# mac '}
        ethx=$(get_ethx_by_mac "$mac" || true)
        if [ -z "$ethx" ]; then
            if [ "$(list_devs | wc -l)" -eq 1 ]; then
                ethx=$(list_devs)
                log "MAC $mac not found; using the only interface: $ethx"
            else
                log "MAC $mac not found; retaining the existing configuration"
            fi
        else
            log "MAC $mac -> $ethx"
        fi
        keep=0
        ;;
    esac
    if [ "$keep" -eq 1 ] && [ -n "$ethx" ]; then
        case "$line" in
        'iface '* | 'auto '* | 'allow-hotplug '*)
            oldname=$(printf '%s' "$line" | awk '{print $2}')
            if [ -n "$oldname" ] && [ "$oldname" != "lo" ] && [ "$oldname" != "$ethx" ]; then
                line=$(printf '%s' "$line" | awk -v d="$ethx" '{$2 = d; print}')
            fi
            ;;
        *' dev '*)
            line=$(printf '%s' "$line" | sed -E "s/( dev )[^ ]+/\1$ethx/g")
            ;;
        *'net.ipv6.conf.'*)
            line=$(printf '%s' "$line" | sed -E "s/net\.ipv6\.conf\.[^ ]+\.(accept_ra|autoconf)=/net.ipv6.conf.$ethx.\1=/g")
            ;;
        esac
    fi
    if [ "$keep" -eq 1 ]; then
        printf '%s\n' "$line" >>"$tmp"
    fi
done <"$IFACES"

if [ -s "$tmp" ]; then
    cat "$tmp" >"$IFACES"
fi
rm -f "$tmp"
REOS_EMBEDDED_ASSET
}

