asset_partman_partman_early_sh() {
cat <<'REOS_EMBEDDED_ASSET'
#!/bin/sh
# Generated by reos.
set -u

# Partman normally expands the final partition to consume the remaining space,
# even when the recipe specifies a maximum. Honor fixed-size recipes instead.
if [ -f /reos-assets/system-size ]; then
    auto=/lib/partman/lib/auto-shared.sh
    pattern='NEW_PARTITION $type $4 $free_space full ${1}000001'
    if [ ! -f "$auto" ] || ! grep -Fq "$pattern" "$auto"; then
        echo 'reos: unsupported partman implementation for --system-size' >&2
        exit 1
    fi
    sed -i 's/NEW_PARTITION $type $4 $free_space full ${1}000001/NEW_PARTITION $type $4 $free_space beginning ${1}000001/' "$auto"
fi

cmdline=$(cat /proc/cmdline)
getarg() {
    for w in $cmdline; do
        case "$w" in
            "$1="*) printf '%s\n' "${w#*=}"; return 0 ;;
        esac
    done
    return 1
}

disk_id=$(getarg reos_disk_id || true)
root_uuid=$(getarg reos_root_partuuid || true)
fallback=$(getarg reos_disk || true)
keep=$(getarg reos_keep || true)

normalize_id() {
    tr 'A-F' 'a-f' | tr -d '{}' | sed 's/^0x//'
}

disk_ident() {
    dev=$1
    if command -v blkid >/dev/null 2>&1; then
        id=$(blkid -s PTUUID -o value "$dev" 2>/dev/null | normalize_id)
        if [ -n "$id" ]; then
            printf '%s\n' "$id"
            return 0
        fi
    fi
    if command -v fdisk >/dev/null 2>&1; then
        id=$(fdisk -l "$dev" 2>/dev/null | grep -i 'disk identifier' | tail -n 1 |
            sed 's/.*: *//' | normalize_id)
        if [ -n "$id" ]; then
            printf '%s\n' "$id"
            return 0
        fi
    fi
    return 1
}

find_disk() {
    if [ -n "$root_uuid" ] && [ -e "/dev/disk/by-partuuid/$root_uuid" ]; then
        part=$(readlink -f "/dev/disk/by-partuuid/$root_uuid" 2>/dev/null) || part=""
        if [ -n "$part" ]; then
            name=${part##*/}
            parent=$(basename "$(readlink -f "/sys/class/block/$name/.." 2>/dev/null)" 2>/dev/null)
            if [ -n "$parent" ] && [ -b "/dev/$parent" ]; then
                printf '%s\n' "/dev/$parent"
                return 0
            fi
        fi
    fi

    if [ -n "$disk_id" ]; then
        for d in /sys/block/*; do
            name=${d##*/}
            case "$name" in
                loop*|sr*|ram*|nbd*|dm-*|md*) continue ;;
            esac
            id=$(disk_ident "/dev/$name" || true)
            if [ -n "$id" ] && [ "$id" = "$disk_id" ]; then
                printf '%s\n' "/dev/$name"
                return 0
            fi
        done
    fi

    if [ -z "$disk_id" ] && [ -z "$root_uuid" ] &&
        [ -n "$fallback" ] && [ -b "$fallback" ]; then
        printf '%s\n' "$fallback"
        return 0
    fi
    return 1
}

if command -v udevadm >/dev/null 2>&1; then
    udevadm settle 2>/dev/null || true
fi

disk=$(find_disk || true)
if [ -z "$disk" ]; then
    echo "partman-early: Cannot locate target disk by identifier (id=${disk_id:-none} partuuid=${root_uuid:-none})" >&2
    disk=/dev/reos-disk-not-found
fi
echo "partman-early: Target disk $disk"

if command -v debconf-set >/dev/null 2>&1; then
    debconf-set partman-auto/disk "$disk"
    debconf-set grub-installer/bootdev "$disk"
fi

postinst=/var/lib/dpkg/info/bootstrap-base.postinst
if [ -f "$postinst" ] && [ ! -f "$postinst.reos" ]; then
    if cp -f "$postinst" "$postinst.reos"; then
        {
            echo 'rm -rf /target/boot/efi/*'
            cat "$postinst.reos"
        } > "$postinst"
        chmod 755 "$postinst"
    fi
fi

if [ -n "$keep" ]; then
    if [ "$disk" = "/dev/reos-disk-not-found" ]; then
        echo "partman-early: Partition preservation requires an available target disk; aborting" >&2
        exit 1
    fi
    if ! command -v parted >/dev/null 2>&1; then
        DEBIAN_FRONTEND=noninteractive anna-install parted-udeb || exit 1
    fi
    if ! command -v parted >/dev/null 2>&1; then
        echo "partman-early: parted is unavailable; aborting" >&2
        exit 1
    fi

    oldIFS=$IFS
    IFS=','
    for n in $keep; do
        [ -n "$n" ] || continue
        if [ ! -b "$disk$n" ] && [ ! -b "${disk}p$n" ]; then
            echo "partman-early: Preserved partition $n does not exist; aborting" >&2
            exit 1
        fi
    done
    IFS=$oldIFS

    numbers=$(parted -s "$disk" print 2>/dev/null | awk '/^ *[0-9]+/ {print $1}' | sort -rn)
    for n in $numbers; do
        case ",$keep," in
            *",$n,"*) continue ;;
        esac
        echo "partman-early: Deleting partition $n"
        parted -s "$disk" rm "$n" || true
    done

    if command -v partprobe >/dev/null 2>&1; then
        partprobe "$disk" 2>/dev/null || true
    fi
fi

exit 0
REOS_EMBEDDED_ASSET
}

