printf '%s' '
d-i apt-setup/enable-source-repositories boolean false
d-i apt-setup/services-select multiselect updates'
if [[ -n ${SecurityRepo:-} && ${SecurityRepo:-} != 0 ]]; then
printf '%s' '
d-i apt-setup/local0/repository string '
printf '%s' "${SecurityRepo:-}"
printf '%s' ' '
printf '%s' "${SecuritySuite:-}"
printf '%s' ' main
d-i apt-setup/local0/source boolean false'
fi
printf '%s' '

tasksel tasksel/first multiselect ssh-server'
if [[ -n ${Install:-} && ${Install:-} != 0 ]]; then
printf '%s' '
d-i pkgsel/include string '
printf '%s' "${Install:-}"
fi
printf '%s' '
d-i pkgsel/upgrade select full-upgrade
popularity-contest popularity-contest/participate boolean false'
if [[ "${Username:-}" == root ]]; then
printf '%s' '
d-i passwd/root-login boolean true
d-i passwd/make-user boolean false
d-i passwd/root-password-crypted password '
printf '%s' "${PasswordHash:-}"
else
printf '%s' '
d-i passwd/root-login boolean false
d-i passwd/make-user boolean true
d-i passwd/user-fullname string '
printf '%s' "${Username:-}"
printf '%s' '
d-i passwd/username string '
printf '%s' "${Username:-}"
printf '%s' '
d-i passwd/user-password-crypted password '
printf '%s' "${PasswordHash:-}"
fi
printf '%s' '

d-i grub-installer/bootdev string '
printf '%s' "${Disk:-}"
printf '%s' '
d-i grub-installer/force-efi-extra-removable boolean true

d-i preseed/late_command string sh /reos-assets/late.sh
d-i finish-install/reboot_in_progress note
'
}

if [[ ${BASH_SOURCE[0]} == "$0" ]]; then main "$@"; fi
